    // Render TemperatureDisplay and TemperatureControls here with props
  );
};

// Create TemperatureDisplay component here
const TemperatureDisplay = (props) => {
  // Return JSX showing temperature value here
  return <h2>Current Temperature: {props.temperature}°C</h2>;
};

// Create TemperatureControls component here
const TemperatureControls = (props) => {
  // Return JSX with two buttons here
  return (
    <div>
      <button onClick={() => props.handleTemperatureChange(1)}>Increase</button>
      <button onClick={() => props.handleTemperatureChange(-1)}>Decrease</button>
    </div>
  );
};
